package app.zhijian.notes.bridge;
import android.app.Activity;import android.webkit.*;import android.util.AtomicFile;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
import app.zhijian.notes.data.PaperDb;import app.zhijian.notes.files.*;import app.zhijian.notes.backup.BackupService;
import app.zhijian.notes.reminder.ReminderScheduler;
public final class NativeBridge {
 private final Activity activity;private final WebView web;private final PaperDb db;private final AttachmentStore files;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final AtomicFile draftFile;private final DocumentController documents;
 private static final Set<String> ALLOWED=new HashSet<>(Arrays.asList("notes.list","notes.get","notes.save","notes.trash","notes.restore","notes.delete","notes.history","notes.checkpoint","notes.restoreVersion","notes.overview","notes.batch","folders.list","folders.save","folders.delete","tags.list","todos.list","todos.save","todos.trash","todos.restore","todos.delete","trash.list","trash.empty","attachments.pick","attachments.pickFile","attachments.openFile","attachments.saveImage","backup.export","backup.import","markdown.export","app.info","app.takeLaunch","app.preferences","app.openLink","reminders.status","reminders.requestPermission"));
 public NativeBridge(Activity a,WebView w,PaperDb d,AttachmentStore files){activity=a;web=w;db=d;this.files=files;draftFile=new AtomicFile(new File(a.getFilesDir(),"draft.json"));documents=new DocumentController(a,this,files,new BackupService(a,d,files.directory));}
 public DocumentController documents(){return documents;}
 public void background(Runnable job){worker.execute(job);}
 public void handleIntent(android.content.Intent intent){background(()->{try{JSONObject launch=null;if(android.content.Intent.ACTION_SEND.equals(intent.getAction())||android.content.Intent.ACTION_SEND_MULTIPLE.equals(intent.getAction()))launch=new ShareImporter(activity,files,db).importIntent(intent);else if(intent.getBooleanExtra("openTodos",false))launch=new JSONObject().put("page","todos");if(launch!=null){activity.getSharedPreferences("paper",0).edit().putString("pendingLaunch",launch.toString()).commit();activity.runOnUiThread(()->web.evaluateJavascript("window.PaperApp&&window.PaperApp.onLaunch&&window.PaperApp.onLaunch()",null));}ReminderScheduler.reconcile(activity,db);}catch(Exception e){activity.runOnUiThread(()->android.widget.Toast.makeText(activity,e.getMessage()==null?"分享导入失败，请重试":e.getMessage(),android.widget.Toast.LENGTH_LONG).show());}});}
 public void refreshReminders(){background(()->{try{ReminderScheduler.reconcile(activity,db);}catch(Exception ignored){}});}
 @JavascriptInterface public void request(String id,String method,String json){
  if(!ALLOWED.contains(method)){reject(id,new IllegalArgumentException("不支持的操作"));return;}
  background(()->{try{JSONObject args=new JSONObject(json);if(method.equals("attachments.pick")||method.equals("attachments.pickFile")||method.startsWith("backup.")||method.equals("markdown.export")){documents.start(id,method,args);return;}
   JSONObject result;
   if(method.equals("app.openLink")){android.net.Uri uri=android.net.Uri.parse(args.getString("url"));if(!"https".equals(uri.getScheme())&&!"http".equals(uri.getScheme()))throw new IllegalArgumentException("不支持的链接");activity.runOnUiThread(()->{try{activity.startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,uri));resolve(id,new JSONObject());}catch(Exception e){reject(id,e);}});return;}
   else if(method.equals("attachments.saveImage")){result=files.saveImage(args.getString("dataUrl"));}
   else if(method.equals("attachments.openFile")){activity.runOnUiThread(()->{try{NoteFileStore.open(activity,args);resolve(id,new JSONObject());}catch(Exception e){reject(id,e);}});return;}
   else if(method.equals("reminders.status"))result=ReminderScheduler.status(activity);
   else if(method.equals("reminders.requestPermission")){activity.runOnUiThread(()->{try{ReminderScheduler.requestPermission(activity);resolve(id,ReminderScheduler.status(activity));}catch(Exception e){reject(id,e);}});return;}
   else if(method.equals("app.takeLaunch")){android.content.SharedPreferences prefs=activity.getSharedPreferences("paper",0);String pending=prefs.getString("pendingLaunch","{}");result=new JSONObject(pending);prefs.edit().remove("pendingLaunch").commit();}
   else if(method.equals("app.preferences")){android.content.SharedPreferences.Editor edit=activity.getSharedPreferences("paper",0).edit();Iterator<String> keys=args.keys();while(keys.hasNext()){String key=keys.next(),value=args.getString(key);if(key.equals("sort")&&Arrays.asList("updated","created","oldest","title").contains(value)||key.equals("layout")&&Arrays.asList("list","grid").contains(value))edit.putString(key,value);else throw new IllegalArgumentException("不支持的显示设置");}if(!edit.commit())throw new IOException("显示设置保存失败，请重试");result=preferences();}
   else if(method.equals("app.info")){result=new JSONObject().put("version",activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionName).put("preferences",preferences()).put("lastBackup",activity.getSharedPreferences("paper",0).getLong("lastBackup",0));JSONObject draft=readDraft();files.prune(db.snapshot(),draft);if(draft!=null)result.put("draft",draft);}
   else{result=db.execute(method,args);if(method.equals("notes.save"))clearDraftIfSaved(result);if(method.equals("notes.delete")||method.equals("trash.empty")){JSONObject draft=readDraft();if(draft!=null){try{db.get("notes",draft.getString("id"));}catch(Exception ignored){synchronized(this){draftFile.delete();}draft=null;}}files.prune(db.snapshot(),draft);}}
   if(method.startsWith("todos.")&&!method.endsWith("list")||method.equals("trash.empty")){try{ReminderScheduler.reconcile(activity,db);}catch(Exception ignored){activity.runOnUiThread(()->android.widget.Toast.makeText(activity,"待办已保存，系统提醒设置暂未更新，请重新打开应用重试",android.widget.Toast.LENGTH_LONG).show());}}
   resolve(id,result);
  }catch(Exception e){reject(id,e);}});
 }
 private JSONObject preferences()throws JSONException{android.content.SharedPreferences prefs=activity.getSharedPreferences("paper",0);return new JSONObject().put("sort",prefs.getString("sort","updated")).put("layout",prefs.getString("layout","list"));}
 @JavascriptInterface public synchronized boolean draft(String json){FileOutputStream out=null;try{if(json.length()>3*1024*1024)return false;JSONObject n=new JSONObject(json);byte[] bytes=n.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>8*1024*1024)return false;out=draftFile.startWrite();out.write(bytes);draftFile.finishWrite(out);return true;}catch(Exception e){if(out!=null)draftFile.failWrite(out);return false;}}
 private synchronized JSONObject readDraft(){try(InputStream in=draftFile.openRead()){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(b.size()+n>8*1024*1024)return null;b.write(buf,0,n);}return new JSONObject(b.toString("UTF-8"));}catch(Exception e){return null;}}
 private synchronized void clearDraftIfSaved(JSONObject saved){JSONObject d=readDraft();if(d!=null&&!d.optString("_draftToken").isEmpty()&&d.optString("_draftToken").equals(saved.optString("_draftToken")))draftFile.delete();}
 public void resolve(String id,JSONObject result){respond(id,true,result);}
 public void reject(String id,Exception error){try{String message=error.getMessage();if(message==null||message.isEmpty())message="操作未完成，请检查可用空间后重试";respond(id,false,new JSONObject().put("code",error instanceof IllegalArgumentException?"VALIDATION":"IO").put("message",message));}catch(JSONException ignored){}}
 private void respond(String id,boolean ok,JSONObject result){String js="window.PaperBridge&&window.PaperBridge.resolve("+JSONObject.quote(id)+","+ok+","+result.toString()+")";activity.runOnUiThread(()->{if(!activity.isDestroyed())web.evaluateJavascript(js,null);});}
 public void close(){worker.execute(db::close);worker.shutdown();}
}
